def chain_ladder_ultimates(cumulative_triangle):
    tri = [list(row) for row in cumulative_triangle]
    n = len(tri)
    if n == 0:
        return []
    ncols = max(len(row) for row in tri)

    # Volume-weighted age-to-age factors from all available adjacent pairs
    factors = []
    for j in range(ncols - 1):
        num = 0.0
        den = 0.0
        for row in tri:
            if len(row) > j + 1 and row[j] is not None and row[j + 1] is not None:
                num += float(row[j + 1])
                den += float(row[j])
        factors.append(num / den if den > 0 else 1.0)

    ultimates = []
    for row in tri:
        last_val = None
        last_idx = -1
        for j, v in enumerate(row):
            if v is not None:
                last_val = v
                last_idx = j
        if last_val is None:
            ultimates.append(0.0)
            continue
        ult = float(last_val)
        for j in range(last_idx, ncols - 1):
            ult *= factors[j]
        ultimates.append(ult)
    return ultimates

