def chain_ladder_ultimates(cumulative_triangle):
    """Volume-weighted chain ladder ultimates from a cumulative claims triangle.

    Each row holds positive cumulative amounts followed by None placeholders.
    Age-to-age factor for development step j -> j+1 is the sum of column j+1
    over rows where both entries are known, divided by the sum of column j
    over those same rows. Each origin row's latest observed cumulative value
    is multiplied by all remaining factors to reach the ultimate.
    """
    if not cumulative_triangle:
        return []

    tri = [list(row) for row in cumulative_triangle]
    n = len(tri)
    m = max(len(row) for row in tri)
    for row in tri:
        while len(row) < m:
            row.append(None)

    factors = []
    for j in range(m - 1):
        numerator = 0.0
        denominator = 0.0
        for i in range(n):
            a = tri[i][j]
            b = tri[i][j + 1]
            if a is not None and b is not None:
                numerator += float(b)
                denominator += float(a)
        if denominator > 0.0:
            factors.append(numerator / denominator)
        else:
            factors.append(1.0)

    ultimates = []
    for i in range(n):
        latest = None
        latest_index = -1
        for j in range(m):
            if tri[i][j] is not None:
                latest = float(tri[i][j])
                latest_index = j
        if latest is None:
            ultimates.append(0.0)
            continue
        value = latest
        for j in range(latest_index, m - 1):
            value *= factors[j]
        ultimates.append(value)

    return ultimates

