def chain_ladder_ultimates(cumulative_triangle):
    """Volume-weighted (chain ladder) ultimates from a cumulative claims triangle.

    cumulative_triangle: list of rows, each row holding positive cumulative
    values followed by None placeholders (square triangle).
    Returns a list with one ultimate claim amount per origin row.
    """
    if not cumulative_triangle:
        return []

    tri = [list(row) for row in cumulative_triangle]
    n_cols = 0
    for row in tri:
        if len(row) > n_cols:
            n_cols = len(row)

    # Volume-weighted age-to-age factors from all available adjacent pairs.
    factors = []
    for j in range(n_cols - 1):
        num = 0.0
        den = 0.0
        for row in tri:
            if len(row) > j + 1:
                a = row[j]
                b = row[j + 1]
                if a is not None and b is not None:
                    num += float(b)
                    den += float(a)
        if den > 0.0:
            factors.append(num / den)
        else:
            factors.append(1.0)

    ultimates = []
    for row in tri:
        last = None
        for j in range(len(row)):
            if row[j] is not None:
                last = j
        if last is None:
            ultimates.append(0.0)
            continue
        value = float(row[last])
        for j in range(last, n_cols - 1):
            value *= factors[j]
        ultimates.append(value)

    return ultimates

